const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const startDate = '2022-10-01';
    const endDate = '2023-03-31';
    const centralValley = ee.FeatureCollection('USGS/WBD/2017/HUC08')
        .filter(ee.Filter.eq('huc8', '18020109')) // A representative HUC8 for the valley floor
        .first()
        .geometry();
    // A broader geometry for the entire valley might be too large for a simple query.
    // Using a large representative polygon is a robust approach.
    const centralValleyGeom = ee.Geometry.Polygon(
        [[[-122.2, 39.5],
          [-122.2, 35.0],
          [-119.0, 35.0],
          [-119.0, 39.5]]]);


    // 2. Data Acquisition & Check
    let precipCollection = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
        .filterDate(startDate, endDate)
        .filterBounds(centralValleyGeom);

    const collectionSize = precipCollection.size().getInfo();
    if (collectionSize === 0) {
        console.log("No precipitation images found for the period.");
        console.log("A: No"); // It is technically possible no rain fell, but more likely a data issue. Let's be strict.
        return;
    }

    // 3. Processing
    const totalPrecipitationMM = precipCollection.sum();

    // 4. Calculation
    // Using a large scale to ensure the calculation completes without timeout
    const scale = 5000;
    const stats = totalPrecipitationMM.reduceRegion({
        reducer: ee.Reducer.mean().combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }),
        geometry: centralValleyGeom,
        scale: scale,
        maxPixels: 1e9
    });

    const precipMM = stats.get('precipitation_mean').getInfo();
    const pixelCount = stats.get('precipitation_count').getInfo();

    if (pixelCount === 0) {
        console.log(`Initial collection size: ${collectionSize}`);
        console.log("No valid pixels found within the geometry after processing.");
        console.log("C2: No Valid Pixels");
        return;
    }

    if (precipMM === null || typeof precipMM === 'undefined') {
        console.log(`Pixel count: ${pixelCount}`);
        console.log("Calculation failed: mean precipitation is null.");
        console.log("C3: Calculation Failure");
        return;
    }

    // 5. Validation & Final Answer
    const inchesConversionFactor = 0.0393701;
    const precipInches = precipMM * inchesConversionFactor;
    const thresholdInches = 15;

    console.log(`Date Range: ${startDate} to ${endDate}`);
    console.log(`Image count: ${collectionSize}`);
    console.log(`Average Total Precipitation (mm): ${precipMM.toFixed(2)}`);
    console.log(`Average Total Precipitation (inches): ${precipInches.toFixed(2)}`);
    console.log(`Threshold (inches): ${thresholdInches}`);
    console.log(`Valid pixel count: ${pixelCount}`);

    if (precipInches >= thresholdInches) {
        console.log("A: Yes");
    } else {
        console.log("B: No");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error('Authentication or Initialization failed:', e);
        console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
    }
}

initEE();
